from lib import *
S = SS('l33')
steps = [
    step("基线:1 万个已跟踪文件加 build/ 下 3,000 个未跟踪的 .o(30 个目录),git status --short 输出 ?? build/。耗时 32.0 ms(5 次中位数)。GIT_TRACE2_PERF 里统计的 lstat 次数是 10000——对每个已跟踪文件做一次 lstat(用 preload-index 多线程并行做完),另外还要扫描 build/ 下的目录找未跟踪文件。", t=tl(S(1)), mark=lidx(S(1), 'lstat 次数', '?? build/'), done=lidx(S(1), '10000', '3000'), kv=KV([['已跟踪文件', '每个 lstat 一次(并行)'], ['未跟踪文件', '要扫描目录才知道'], ['基线', '32.0 ms / 10000 次 lstat']], ['已跟踪文件'])),
    step("在 1 万个文件的仓库上依次打开两个加速:core.untrackedCache=true 先用 git update-index --test-untracked-cache 检查文件系统(Testing mtime … OK),index 里多出 UNTR 扩展;打开后 git status 28.3 ms,lstat 次数仍是 10000。再打开 core.fsmonitor=true:git 自动启动守护进程(git fsmonitor--daemon status 显示 is watching),index 里再多出 FSMN 扩展;git status 30.1 ms,但 lstat 次数降到 0。lstat 次数从 10000 变成 0,耗时却没有变——1 万次 lstat 并行起来本来只要约 9 毫秒,没什么可省的。", t=tl(S(2)), mark=lidx(S(2), 'FSMN', 'lstat 次数 0', 'UNTR'), done=lidx(S(2), 'untracked cache: 28.3', 'is watching', '1 万个文件时'), b=bars([['基线', 32.0, '32.0 ms'], ['+ untracked cache', 28.3, '28.3 ms'], ['+ fsmonitor', 30.1, '30.1 ms']], 32.0, mark=[2], done=[0, 1]), kv=KV([['UNTR 扩展', '目录扫描结果缓存'], ['FSMN 扩展', '守护进程的“上次查询标记”'], ['1 万个文件', 'lstat 从 10000 降到 0,耗时没变']], ['FSMN 扩展'])),
    step("放大到 10 万个已跟踪文件加 2 万个未跟踪文件:基线 git status 184.4 ms,lstat 次数 100000。只开 untracked cache 降到 102.8 ms;两个都开降到 38.3 ms,lstat 次数 0(约 4.8 倍);只开 fsmonitor 是 88.3 ms。untracked cache 省的是扫描目录的时间,fsmonitor 省的是 lstat 全部文件的时间,两个叠加才能把 10 万文件的 status 压到 38 ms。", t=tl(S(3)), mark=lidx(S(3), '两个都开', '只开 fsmonitor'), done=lidx(S(3), '基线 git status', '+ untracked cache'), b=bars([['基线', 184.4, '184.4 ms'], ['untracked cache', 102.8, '102.8 ms'], ['只开 fsmonitor', 88.3, '88.3 ms'], ['两个都开', 38.3, '38.3 ms']], 184.4, mark=[3], done=[0, 1, 2]), kv=KV([['untracked cache', '省目录扫描'], ['fsmonitor', '省 lstat(100000 → 0)'], ['叠加', '184.4 → 38.3 ms']], ['叠加'])),
    step("守护进程是怎么跟得上改动的:在 fsmonitor 开着(这里只开 fsmonitor)的 10 万文件仓库里改一个已跟踪文件、新建一个未跟踪文件,git status 马上输出 M src/d123/f061700.txt 和 ?? build/,耗时 89.9 ms,没有退回到全量扫描(基线是 184.4 ms)。守护进程一直在监听文件系统事件,git status 只问它“上次以来哪些路径变了”。", t=tl(S(4)), mark=lidx(S(4), ' M src/d123/f061700.txt'), done=lidx(S(4), '?? build/', 'git status: 89.9'), kv=KV([['守护进程', '监听文件系统事件'], ['git status', '只查询“上次以来变了什么”'], ['结果', '改动即时可见,不用全量 lstat']], ['守护进程'])),
    step("代价:一个常驻进程,每个仓库一个。.git 里出现 fsmonitor--daemon 目录和 fsmonitor--daemon.ipc(unix socket)。git config --unset core.fsmonitor 之后守护进程仍然在 watching,不会自己退出;要手工 git fsmonitor--daemon stop,之后 status 显示 not watching,ipc 文件消失(目录还在)。全部关闭后 10 万文件的 git status 回到 154.8 ms。", t=tl(S(5)), mark=lidx(S(5), 'is watching', 'is not watching', 'fsmonitor--daemon.ipc'), done=lidx(S(5), 'git config --unset core.fsmonitor', 'stop'), kv=KV([['常驻进程', '每个仓库一个'], ['关配置', '不会停进程'], ['停进程', 'git fsmonitor--daemon stop']], ['常驻进程'])),
]
A = mkarti('l33', 33, 'Git,fsmonitor,untracked cache,git status,性能,真实验证,动画演示',
    '在 1 万与 10 万个文件的仓库上实测 untracked cache 和 fsmonitor:1 万文件时 lstat 次数从 10000 降到 0 但耗时都在 30 ms 上下;10 万文件时 git status 从 184.4 ms 降到 untracked cache 的 102.8 ms、两个叠加的 38.3 ms;改动能即时被守护进程发现;守护进程是常驻进程,关掉配置不会自己退出。',
    '大仓库里 git status 为什么慢,untracked cache 和 fsmonitor 又各自省了什么?这篇在 1 万和 10 万个文件的仓库上分别测:先看 lstat 次数,再看耗时,最后看守护进程的代价。结论有点出人意料:1 万个文件时它们几乎没用。',
    [('184 → 38 ms', '10 万个已跟踪文件 + 2 万个未跟踪文件时 git status 的耗时:基线与 untracked cache + fsmonitor 叠加'), ('10000 → 0', '打开 fsmonitor 之后 git status 的 lstat 次数,但 1 万个文件时耗时没有变'), ('UNTR / FSMN', '两个加速分别在 index 里增加的扩展块')],
    [('基线', '<p>git status 要对每个已跟踪文件 lstat 一次(用 <code>preload-index</code> 并行),还要扫描目录找出未跟踪的文件。1 万个文件时整个 status 只要约 30 ms。</p>'),
     ('untracked cache 与 fsmonitor', '<p><code>core.untrackedCache</code> 把每个目录上次的扫描结果(及目录 mtime)存进 index 的 <code>UNTR</code> 扩展,目录没变就不再扫描。<code>core.fsmonitor</code> 启动守护进程监听文件系统事件,index 的 <code>FSMN</code> 扩展记着上次查询的标记,status 只需问“之后哪些路径变了”,不再 lstat 全部文件。</p>'),
     ('规模决定收益', '<p>1 万个文件时 lstat 从 10000 次降到 0,耗时却没变(并行 lstat 本来就快)。10 万个文件时才显出差别:184 ms 降到 untracked cache 的 103 ms,两者叠加的 38 ms。仓库不大时不值得打开。</p>'),
     ('改动怎么被发现', '<p>守护进程持续接收文件系统事件。改一个文件、新建一个文件之后 status 立刻能看到,仍不需要全量扫描。</p>'),
     ('代价', '<p>每个仓库一个常驻进程,有 ipc socket。把 <code>core.fsmonitor</code> 配置关掉并不会停掉它,需要 <code>git fsmonitor--daemon stop</code>。</p>')],
    steps,
    [ENV_I_GIT + '。仓库由脚本生成(10,000 / 100,000 个很小的文本文件);耗时 5 次中位数,含进程启动;lstat 次数来自 GIT_TRACE2_PERF 的 sum_lstat;fsmonitor 用 git 自带的 fsmonitor--daemon(macOS 的 FSEvents);每次测量前先让 index 刷新(避开 racy 窗口);同一台机器上各轮的基线有波动(10 万文件的“全部关闭”是 154.8 ms,基线是 184.4 ms)',
     '没有验证:Linux 上的 inotify 实现;Watchman 等第三方 fsmonitor 钩子;网络文件系统与 fsmonitor 的兼容;守护进程占用的内存;git status 之外(git diff、git add)的收益;core.untrackedCache 在 mtime 精度不足的文件系统上的退化'],
    'untracked cache 与 fsmonitor')
